<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<div class="page-heading"><div><h1>Brands</h1><p>Manage product manufacturers.</p></div><a class="button" href="/admin/brands/create">Add brand</a></div>
<?php if($flash):?><p class="flash flash-<?= $e($flash['type']) ?>" role="status"><?= $e($flash['message']) ?></p><?php endif;?>
<section class="panel table-wrap"><table><thead><tr><th>Name</th><th>Slug</th><th>Products</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($brands as $brand):?><tr><td><?= $e($brand['name']) ?></td><td><code><?= $e($brand['slug']) ?></code></td><td><?= $e($brand['product_count']) ?></td><td><span class="badge <?= (int)$brand['is_active']===1?'active':'hidden' ?>"><?= (int)$brand['is_active']===1?'Active':'Hidden' ?></span></td><td class="actions"><a href="/admin/brands/<?= $e($brand['id']) ?>/edit">Edit</a><form method="post" action="/admin/brands/<?= $e($brand['id']) ?>/status"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="is_active" value="<?= (int)$brand['is_active']===1?'0':'1' ?>"><button class="link-button" type="submit"><?= (int)$brand['is_active']===1?'Hide':'Activate' ?></button></form><form method="post" action="/admin/brands/<?= $e($brand['id']) ?>/delete" data-confirm="Delete this brand? This is blocked while products are assigned."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><button class="link-button danger" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if($brands===[]):?><p>No brands yet.</p><?php endif;?></section>
